"""Share-link event log: one place that defines what can be recorded and how.

Two families of events share one table (``ShareLinkEvent``):

* **server events** - generated by the access flow itself (attempts, requests, grants...);
  a viewer can never submit these;
* **client events** - viewer behaviour reported by the viewer's JavaScript (print attempts,
  copy attempts, ...). Only types listed in ``CLIENT_EVENT_TYPES`` are accepted.

To add a new tracked behaviour: add a constant here, put it in ``CLIENT_EVENT_TYPES`` and
report it from ``frontend/src/lib/viewerEvents.js``. Nothing else needs to change; the
owner's access log, the analytics filters and webhooks pick it up by type.

Remember that client events are best-effort signals from an untrusted browser: they show
what a viewer's page *reported*, they cannot prove what the viewer did not do.
"""
import logging
import time

from backend.utils import get_client_ip

from .models import ShareLinkEvent

logger = logging.getLogger(__name__)


class EventType:
    # --- server events: the access flow -------------------------------------------------
    ACCESS_ATTEMPT = 'access_attempt'                      # opened/used a link without being authorized
    ACCESS_REQUEST = 'access_request'                      # submitted an email asking for access
    ACCESS_REQUEST_ALLOWED = 'access_request_allowed'      # ...and it is on the allow-list (code sent)
    ACCESS_REQUEST_DENIED = 'access_request_denied'        # ...and it is not (nothing sent)
    ACCESS_REQUEST_THROTTLED = 'access_request_throttled'  # too many requests, ignored
    ACCESS_GRANTED = 'access_granted'                      # correct code entered, session authorized
    ACCESS_CODE_INVALID = 'access_code_invalid'            # wrong / expired / used code
    INVITATION_SENT = 'invitation_sent'                    # owner added an email, invitation mailed
    ACCESS_REVOKED = 'access_revoked'                      # owner removed an email
    DOMAIN_ADDED = 'domain_added'                          # owner added a domain-wide rule
    SPOTLIGHT_LIMIT = 'spotlight_limit'                    # too many spotlight patch requests, ignored

    # --- client events: viewer behaviour ------------------------------------------------
    PRINT_ATTEMPT = 'print_attempt'
    COPY_ATTEMPT = 'copy_attempt'
    CONTEXT_MENU = 'context_menu'
    SCREENSHOT_KEY = 'screenshot_key'
    TAB_HIDDEN = 'tab_hidden'
    SAVE_ATTEMPT = 'save_attempt'          # Ctrl/Cmd+S (saving the page)
    DEVTOOLS_KEY = 'devtools_key'          # F12, Ctrl+Shift+I/J/C, Ctrl+U (inspect / view source)
    WINDOW_BLUR = 'window_blur'            # the window lost focus
    DRAG_ATTEMPT = 'drag_attempt'          # dragging the page image out
    DEVTOOLS_OPEN = 'devtools_open'        # developer tools seem to be open (window-size gap or console probe)
    TAMPER_DETECTED = 'tamper_detected'    # the page's own browser functions were patched (finding, not proof)
    AUTOMATION_DETECTED = 'automation_detected'   # a browser driven by a program (also set by the server from the user agent)

    # --- server findings about how pages were requested -------------------------------
    NON_BROWSER_REQUEST = 'non_browser_request'   # a page request that did not come from the viewer's script
    TILES_WITHOUT_CURSOR = 'tiles_without_cursor' # many tiles fetched while no cursor movement was ever reported


SERVER_EVENT_TYPES = frozenset({
    EventType.ACCESS_ATTEMPT,
    EventType.ACCESS_REQUEST,
    EventType.ACCESS_REQUEST_ALLOWED,
    EventType.ACCESS_REQUEST_DENIED,
    EventType.ACCESS_REQUEST_THROTTLED,
    EventType.ACCESS_GRANTED,
    EventType.ACCESS_CODE_INVALID,
    EventType.INVITATION_SENT,
    EventType.ACCESS_REVOKED,
    EventType.SPOTLIGHT_LIMIT,
    EventType.DOMAIN_ADDED,
    EventType.NON_BROWSER_REQUEST,
    EventType.TILES_WITHOUT_CURSOR,
})

CLIENT_EVENT_TYPES = frozenset({
    EventType.PRINT_ATTEMPT,
    EventType.COPY_ATTEMPT,
    EventType.CONTEXT_MENU,
    EventType.SCREENSHOT_KEY,
    EventType.TAB_HIDDEN,
    EventType.SAVE_ATTEMPT,
    EventType.DEVTOOLS_KEY,
    EventType.WINDOW_BLUR,
    EventType.DRAG_ATTEMPT,
    EventType.TAMPER_DETECTED,
    EventType.AUTOMATION_DETECTED,
    EventType.DEVTOOLS_OPEN,
})

ALL_EVENT_TYPES = SERVER_EVENT_TYPES | CLIENT_EVENT_TYPES

CATEGORY_ACCESS = 'access'
CATEGORY_BEHAVIOR = 'behavior'


def event_category(event_type: str) -> str:
    return CATEGORY_ACCESS if event_type in SERVER_EVENT_TYPES else CATEGORY_BEHAVIOR


def event_types_for_category(category: str) -> frozenset:
    if category == CATEGORY_ACCESS:
        return SERVER_EVENT_TYPES
    if category == CATEGORY_BEHAVIOR:
        return CLIENT_EVENT_TYPES
    return frozenset()


MAX_METADATA_KEYS = 12
MAX_METADATA_VALUE_LENGTH = 200


def sanitize_metadata(metadata) -> dict:
    """Keep a small flat dict of scalars; drop everything else (client input is untrusted)."""
    if not isinstance(metadata, dict):
        return {}
    clean = {}
    for key, value in list(metadata.items())[:MAX_METADATA_KEYS]:
        key = str(key)[:40]
        if isinstance(value, bool) or value is None or isinstance(value, (int, float)):
            clean[key] = value
        elif isinstance(value, str):
            clean[key] = value[:MAX_METADATA_VALUE_LENGTH]
    return clean


def record_event(link, event_type: str, request=None, email: str = '', metadata=None) -> ShareLinkEvent:
    """Append an event for ``link``. ``email`` is normalised; secrets must never be passed in metadata."""
    ip_address = None
    user_agent = ''
    if request is not None:
        ip_address = get_client_ip(request) or None
        user_agent = (request.META.get('HTTP_USER_AGENT', '') or '')[:512]
    return ShareLinkEvent.objects.create(
        share_link=link,
        event_type=event_type,
        email=(email or '').strip().lower(),
        ip_address=ip_address,
        user_agent=user_agent,
        metadata=sanitize_metadata(metadata),
    )


def record_event_once(request, link, event_type: str, window_seconds: int = 300, email: str = '', metadata=None):
    """Like ``record_event`` but at most once per session / link / type within the window."""
    now = time.time()
    marker = f"{link.id}:{event_type}"
    seen = dict(request.session.get('event_dedupe', {}))
    last = seen.get(marker)
    if last is not None and now - last < window_seconds:
        return None
    seen[marker] = now
    # keep the session small
    if len(seen) > 50:
        seen = dict(sorted(seen.items(), key=lambda item: item[1])[-25:])
    request.session['event_dedupe'] = seen
    return record_event(link, event_type, request, email, metadata)
